<?php $pageTitle='Student Registration'; require 'config.php'; $msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $s=$conn->prepare('INSERT INTO students(full_name,gender,dob,phone,email,address,district,state,qualification,programme,message) VALUES(?,?,?,?,?,?,?,?,?,?,?)'); $s->bind_param('sssssssssss',$_POST['full_name'],$_POST['gender'],$_POST['dob'],$_POST['phone'],$_POST['email'],$_POST['address'],$_POST['district'],$_POST['state'],$_POST['qualification'],$_POST['programme'],$_POST['message']); $msg=$s->execute()?'Registration submitted successfully.':'Unable to submit registration.'; } include 'header.php'; ?><section class="page-head"><div class="container"><div class="eyebrow">STUDENTS</div><h1>Student Registration</h1></div></section><section class="section"><div class="container form"><p class="muted">Submit your interest. PACPET can contact you regarding available programmes and batches.</p><?php if($msg): ?><div class="flash"><?=e($msg)?></div><?php endif; ?><form method="post"><div class="form-grid"><div><label>Full Name *</label><input name="full_name" required></div><div><label>Gender</label><select name="gender"><option>Male</option><option>Female</option><option>Other</option></select></div><div><label>Date of Birth</label><input type="date" name="dob"></div><div><label>Phone *</label><input name="phone" required></div><div><label>Email</label><input type="email" name="email"></div><div><label>Qualification</label><input name="qualification"></div><div><label>District</label><input name="district"></div><div><label>State</label><input name="state"></div><div class="full"><label>Programme</label><select name="programme"><option>English Training</option><option>Phule Studies</option><option>Ambedkar Studies</option><option>Philosophy</option><option>Residential Programme</option></select></div><div class="full"><label>Address</label><textarea name="address"></textarea></div><div class="full"><label>Message</label><textarea name="message"></textarea></div></div><button class="btn">Submit Registration</button></form></div></section><?php include 'footer.php'; ?>
